1	import { describe, it, expect } from "vitest";
2	import { nextGeneration } from "./game-of-life.js";
3	
4	describe("Game of Life - Next Generation", () => {
5	  // Simplest case: empty grid
6	  it("should return an empty array for an empty grid", () => {
7	    expect(nextGeneration([])).toEqual([]);
8	  });
9	
10	  // Single cell dies (underpopulation, 0 neighbors)
11	  it("should kill a single live cell — [(0,0)] → []", () => {
12	    expect(nextGeneration([[0, 0]])).toEqual([]);
13	  });
14	
15	  // Rule 1 – Underpopulation (live cell with < 2 neighbors dies)
16	  it("should kill both cells with only 1 neighbor each — [(0,1),(1,1)] → []", () => {
17	    expect(nextGeneration([[0, 1], [1, 1]])).toEqual([]);
18	  });
19	
20	  // Rule 4 – Reproduction (dead cell with exactly 3 neighbors becomes alive)
21	  it("should bring a dead cell with exactly 3 neighbors to life — (1,1) becomes alive", () => {
22	    const result = nextGeneration([[0, 0], [1, 0], [0, 1]]);
23	    expect(result).toContainEqual([1, 1]);
24	  });
25	
26	  // Rule 2 – Survival (live cell with 2 or 3 neighbors lives on)
27	  it("should keep a live cell (0,0) with 2 neighbors alive", () => {
28	    // (0,0) has live neighbors (1,0) and (0,1) → survives
29	    const result = nextGeneration([[0, 0], [1, 0], [0, 1]]);
30	    expect(result).toContainEqual([0, 0]);
31	  });
32	
33	  // Rule 3 – Overpopulation (live cell with > 3 neighbors dies)
34	  it("should kill the center cell (1,1) with 4 neighbors", () => {
35	    // (1,1) live with 4 live neighbors at the corners → dies
36	    const result = nextGeneration([[1, 1], [0, 0], [2, 0], [0, 2], [2, 2]]);
37	    expect(result).not.toContainEqual([1, 1]);
38	  });
39	
40	  // Block (still life) — unchanged
41	  it("should leave a block unchanged — [(0,0),(1,0),(0,1),(1,1)]", () => {
42	    const result = nextGeneration([[0, 0], [1, 0], [0, 1], [1, 1]]);
43	    expect(result).toHaveLength(4);
44	    expect(result).toContainEqual([0, 0]);
45	    expect(result).toContainEqual([1, 0]);
46	    expect(result).toContainEqual([0, 1]);
47	    expect(result).toContainEqual([1, 1]);
48	  });
49	
50	  // Blinker (oscillator) — Gen 0 → Gen 1
51	  it("should transform blinker [(0,0),(0,1),(0,2)] → [(-1,1),(0,1),(1,1)]", () => {
52	    const result = nextGeneration([[0, 0], [0, 1], [0, 2]]);
53	    expect(result).toHaveLength(3);
54	    expect(result).toContainEqual([-1, 1]);
55	    expect(result).toContainEqual([0, 1]);
56	    expect(result).toContainEqual([1, 1]);
57	  });
58	
59	  // Negative coordinates handled
60	  it.todo("should handle negative coordinates (blinker Gen 1 → Gen 2)");
61	});
